    function dungNut(the, thuocTinh, con) {
        var e = document.createElementNS('http://www.w3.org/2000/svg', the);
        Object.keys(thuocTinh).forEach(function (k) {
            e.setAttribute(k, String(thuocTinh[k]));
        });
        (con || []).forEach(function (c) { e.appendChild(dungNut(c[0], c[1])); });
        return e;
    }

    function thay(el, ten) {
        var duLieu = ICONS[ten];
        if (!duLieu) {
            // Thiếu icon nghĩa là quên chạy lại build/tao_lucide.cjs sau khi
            // thêm icon mới. Báo thẳng tên ra console, chứ để im thì triệu
            // chứng duy nhất là "chỗ đó trống trơn" và rất khó lần.
            console.warn('[lucide] thiếu icon "' + ten + '" — chạy: node build/tao_lucide.cjs');
            return;
        }

        var tt = {};
        Object.keys(MAC_DINH).forEach(function (k) { tt[k] = MAC_DINH[k]; });

        // Chép mọi thuộc tính của thẻ gốc sang svg, để class Tailwind
        // (w-5 h-5 text-blue-600...) và aria-* không bị mất.
        Array.prototype.forEach.call(el.attributes, function (a) {
            if (a.name === 'data-lucide') return;
            tt[a.name] = a.value;
        });
        tt['class'] = ('lucide lucide-' + ten + ' ' + (el.getAttribute('class') || '')).trim();

        el.parentNode.replaceChild(dungNut('svg', tt, duLieu), el);
    }

    function createIcons(tuyChon) {
        var goc = (tuyChon && tuyChon.root) || document;
        Array.prototype.forEach.call(goc.querySelectorAll('[data-lucide]'), function (el) {
            thay(el, el.getAttribute('data-lucide'));
        });
    }

    return { createIcons: createIcons, icons: ICONS };
